import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> dict(side, price, qty, active)
    seq_counter = 0

    def add_resting(order_id, side, price, qty, seq):
        book[order_id] = {'side': side, 'price': price, 'qty': qty, 'active': True, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, order_id))
        else:
            heapq.heappush(sell_heap, (price, seq, order_id))

    def clean_buy_top():
        while buy_heap:
            negprice, s, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'buy':
                heapq.heappop(buy_heap)
                continue
            return True
        return False

    def clean_sell_top():
        while sell_heap:
            price, s, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'sell':
                heapq.heappop(sell_heap)
                continue
            return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            while remaining > 0 and clean_sell_top():
                sp, sseq, soid = sell_heap[0]
                if typ != 'market':
                    if sp > price:
                        break
                sinfo = book[soid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, soid, sinfo['price'], trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)
            if remaining > 0 and typ == 'limit':
                add_resting(oid, side, price, remaining, my_seq)
        else:  # sell
            while remaining > 0 and clean_buy_top():
                negbp, bseq, boid = buy_heap[0]
                bp = -negbp
                if typ != 'market':
                    if bp < price:
                        break
                binfo = book[boid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([boid, oid, binfo['price'], trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)
            if remaining > 0 and typ == 'limit':
                add_resting(oid, side, price, remaining, my_seq)

    return trades

